697			pop := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
698			report := CompareSnapshots(empty, pop)
699			if got, want := report.NewDatasets, []string{"A", "B"}; !reflect.DeepEqual(got, want) {
700				t.Errorf("NewDatasets = %v, want %v", got, want)
701			}
702			if !reflect.DeepEqual(report.AddedRelations, []Relation{{Upstream: "A", Downstream: "B"}}) {
703				t.Errorf("AddedRelations = %v", report.AddedRelations)
704			}
705			if len(report.RootSourceChanges) != 0 {
706				t.Errorf("new datasets must not appear in root source changes: %v", report.RootSourceChanges)
707			}
708		})
709	
710		t.Run("populated to empty lists only removed nodes and edges", func(t *testing.T) {
711			empty := snapshotOf(t, `{"datasets":[]}`)
712			pop := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`)
713			report := CompareSnapshots(pop, empty)
714			if got, want := report.RemovedDatasets, []string{"A", "B"}; !reflect.DeepEqual(got, want) {
715				t.Errorf("RemovedDatasets = %v, want %v", got, want)
716			}
717			if !reflect.DeepEqual(report.RemovedRelations, []Relation{{Upstream: "A", Downstream: "B"}}) {
718				t.Errorf("RemovedRelations = %v", report.RemovedRelations)
719			}
720			if len(report.RootSourceChanges) != 0 {
721				t.Errorf("removed datasets must not appear in root source changes: %v", report.RootSourceChanges)
722			}
723		})
724	}
725	
726	func TestCompareEmptyListsEncodeAsArrays(t *testing.T) {
727		snap := snapshotOf(t, `{"datasets":[]}`)
728		data, err := json.Marshal(CompareSnapshots(snap, snap))
729		if err != nil {
730			t.Fatalf("marshal report: %v", err)
731		}
732		jsonText := string(data)
733		if strings.Contains(jsonText, "null") {
734			t.Errorf("empty report encoded a null list: %s", jsonText)
735		}
736		for _, key := range []string{`"newDatasets":`, `"removedDatasets":`, `"changedDatasets":`, `"addedRelations":`, `"removedRelations":`, `"rootSourceChanges":`} {
737			if !strings.Contains(jsonText, key+"[]") {
738				t.Errorf("report key %s not encoded as an empty array:\n%s", key, jsonText)
739			}
740		}
741	}
742	
743	func TestCompareDeterministicBytes(t *testing.T) {
744		oldA := snapshotOf(t, `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]},{"name":"C","upstreams":["B"]}]}`)
745		// Same graph semantics, fed in shuffled/duplicated form.
746		oldB := snapshotOf(t, `{"datasets":[{"name":"C","upstreams":["B"]},{"name":"B","upstreams":["A","A"]},{"name":"A","upstreams":[]}]}`)
747		newA := snapshotOf(t, `{"datasets":[{"name":"X","upstreams":[]},{"name":"B","upstreams":["X"]},{"name":"C","upstreams":["B"]}]}`)
748	
749		r1 := CompareSnapshots(oldA, newA)
750		r2 := CompareSnapshots(oldB, newA)
751		b1, _ := json.Marshal(r1)
752		b2, _ := json.Marshal(r2)
753		if string(b1) != string(b2) {
754			t.Fatalf("compare bytes differ for semantically equal old snapshots:\n%s\n%s", b1, b2)
755		}
756	}
757	
758	func TestCompareNameCasingAndSpacingPreserved(t *testing.T) {
759		oldSnap := snapshotOf(t, `{"datasets":[{"name":" Raw ","upstreams":[]},{"name":"RAW","upstreams":[" Raw "]}]}`)
760		newSnap := snapshotOf(t, `{"datasets":[{"name":" Raw ","upstreams":[]},{"name":"RAW","upstreams":[]}]}`)
761		report := CompareSnapshots(oldSnap, newSnap)
762		want := []RootSourceChange{{Dataset: "RAW", OldRoots: []string{" Raw "}, NewRoots: []string{"RAW"}}}
763		if !reflect.DeepEqual(report.RootSourceChanges, want) {
764			t.Errorf("RootSourceChanges = %#v, want %#v", report.RootSourceChanges, want)
765		}
766	}
767	
768	func assertEmptyReport(t *testing.T, report *CompareReport) {
769		t.Helper()
770		if len(report.NewDatasets) != 0 || len(report.RemovedDatasets) != 0 || len(report.ChangedDatasets) != 0 ||
771			len(report.AddedRelations) != 0 || len(report.RemovedRelations) != 0 || len(report.RootSourceChanges) != 0 {
772			t.Fatalf("expected empty report, got %+v", report)
773		}
774		// Slices must be non-nil so JSON renders [].
775		if report.NewDatasets == nil || report.RemovedDatasets == nil || report.ChangedDatasets == nil ||
776			report.AddedRelations == nil || report.RemovedRelations == nil || report.RootSourceChanges == nil {
777			t.Errorf("empty report contains nil slices: %+v", report)
778		}
779	}
