1	//go:build unix
2	
3	package main
4	
5	// Cross-process regression coverage for concurrent `snapshot` saves.
6	//
7	// The in-process test TestCLISnapshotConcurrentSameContent only proves that
8	// goroutines inside one command process serialize. These tests instead launch
9	// two INDEPENDENT command binaries that submit to the SAME snapshot target with
10	// overlapping execution:
11	//
12	//   - an external helper process first takes the sibling flock the snapshot
13	//     command uses, so neither command can enter its check-then-write section;
14	//   - both commands are started and confirmed (via /proc/locks) blocked on that
15	//     very lock before the helper is killed and the kernel hands the lock to
16	//     one of them;
17	//   - the two saves are therefore simultaneous submissions that race the lock,
18	//     never two saves run one after the other, and no winner is preselected.
19	//
20	// Everything asserted here is observable user behavior: per-command exit code,
21	// exact stdout/stderr, and the final snapshot file. No chain network is used.
22	
23	import (
24		"bufio"
25		"bytes"
26		"fmt"
27		"os"
28		"os/exec"
29		"path/filepath"
30		"reflect"
31		"sort"
32		"strconv"
33		"strings"
34		"syscall"
35		"testing"
36		"time"
37	
38		"github.com/asdhoaiqqq/chainledger-governance/chainledger"
39	)
40	
41	// lockHelperMode is the hidden argument under which the test binary itself
42	// acts as an external lock holder on the snapshot target's sibling lock file.
43	const lockHelperMode = "--chainledger-test-lock-helper"
44	
45	// lockHelperTTL bounds a helper whose parent died before killing it; a normal
46	// test always kills it explicitly far sooner.
47	const lockHelperTTL = 60 * time.Second
48	
49	// snapshotCLIBin is the freshly built real command binary, shared by every
50	// test so `go build` runs once per `go test` invocation.
51	var snapshotCLIBin string
52	
53	// TestMain builds the command binary once and also implements the external
54	// lock-holder helper mode (the test binary re-enters here as a subprocess).
55	func TestMain(m *testing.M) {
56		if len(os.Args) >= 2 && os.Args[1] == lockHelperMode {
57			os.Exit(runLockHelper(os.Args[2:]))
58		}
59	
60		dir, err := os.MkdirTemp("", "chainledger-snapshot-bin-")
61		if err != nil {
62			fmt.Fprintln(os.Stderr, "cannot make temp build dir:", err)
63			os.Exit(1)
64		}
65		snapshotCLIBin = filepath.Join(dir, "chainledger")
66		build := exec.Command("go", "build", "-o", snapshotCLIBin, ".")
67		build.Stderr = os.Stderr
68		if err := build.Run(); err != nil {
69			fmt.Fprintln(os.Stderr, "cannot build chainledger test binary:", err)
70			os.RemoveAll(dir)
71			os.Exit(1)
72		}
73	
74		code := m.Run()
75		os.RemoveAll(dir)
76		os.Exit(code)
77	}
78	
79	// runLockHelper takes an exclusive kernel flock on the very sibling lock file
80	// the snapshot command uses. It deliberately performs the flock with a raw
81	// syscall rather than reusing the product's acquireLock: the gate is test
82	// infrastructure and must keep working even when a deliberate fault disables
83	// locking inside the command under test. A flock on the same file inode is
84	// kernel-level and code-agnostic, so this still blocks the commands' own
85	// acquireLock calls. It prints "locked" once the gate is closed and holds the
86	// lock until killed.
87	func runLockHelper(args []string) int {
88		if len(args) != 1 {
89			fmt.Fprintln(os.Stderr, "usage: test-binary", lockHelperMode, "<lock-file>")
90			return 2
91		}
92		f, err := os.OpenFile(args[0], os.O_CREATE|os.O_RDWR, 0o644)
93		if err != nil {
94			fmt.Fprintln(os.Stderr, "helper cannot open lock:", err)
95			return 1
96		}
97		defer f.Close()
98		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
99			fmt.Fprintln(os.Stderr, "helper cannot flock:", err)
100			return 1
101		}
102		defer syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
103		// os.Stdout is an unbuffered os.File, so Println reaches the pipe
104		// immediately; do NOT call os.Stdout.Sync() — fsync on a pipe fails with
105		// EINVAL and must not abort the helper before it has held the lock.
106		fmt.Println("locked")
107		time.Sleep(lockHelperTTL)
108		return 0
109	}
110	
111	// lockGate is an external process holding the snapshot target's lock. Releasing
112	// the gate (killing the holder) lets the kernel grant the lock to exactly one
113	// of the waiting commands.
114	type lockGate struct {
115		cmd *exec.Cmd
116	}
117	
118	// holdLockGate starts the helper and blocks until it has confirmed (by
119	// printing "locked") that it holds the lock, so any snapshot command started
120	// afterwards is guaranteed to block.
121	func holdLockGate(t *testing.T, lockPath string) *lockGate {
122		t.Helper()
123		exe, err := os.Executable()
124		if err != nil {
125			t.Fatalf("locate test binary: %v", err)
126		}
127		cmd := exec.Command(exe, lockHelperMode, lockPath)
128		stdout, err := cmd.StdoutPipe()
129		if err != nil {
130			t.Fatalf("helper stdout pipe: %v", err)
131		}
132		cmd.Stderr = os.Stderr
133		if err := cmd.Start(); err != nil {
134			t.Fatalf("start lock helper: %v", err)
135		}
136		t.Cleanup(func() {
137			_ = cmd.Process.Kill()
138			_ = cmd.Wait()
139		})
140	
141		ready := make(chan bool, 1)
142		go func() {
143			sc := bufio.NewScanner(stdout)
144			ready <- sc.Scan() && sc.Text() == "locked"
145		}()
146		select {
147		case ok := <-ready:
148			if !ok {
149				t.Fatal("lock helper exited without reporting the lock")
150			}
151		case <-time.After(10 * time.Second):
152			t.Fatal("lock helper never acquired the lock")
153		}
154		return &lockGate{cmd: cmd}
155	}
156	
157	// release kills the holder; its process death releases the flock atomically.
158	func (g *lockGate) release() {
159		_ = g.cmd.Process.Kill()
160		_ = g.cmd.Wait()
161	}
162	
163	// blockedWaiterPIDs returns the PIDs of processes with an FLOCK request queued
164	// (the "/proc/locks" lines starting with "->") on the given lock file's inode.
165	// The holder's own granted lock has no "->" prefix and is excluded.
166	func blockedWaiterPIDs(t *testing.T, lockPath string) map[int]bool {
167		t.Helper()
168		fi, err := os.Stat(lockPath)
169		if err != nil {
170			t.Fatalf("stat lock file: %v", err)
171		}
172		st, ok := fi.Sys().(*syscall.Stat_t)
173		if !ok {
174			t.Fatalf("lock file stat is not a unix stat_t: %T", fi.Sys())
175		}
176		inodeSuffix := ":" + strconv.FormatUint(st.Ino, 10)
177	
178		data, err := os.ReadFile("/proc/locks")
179		if err != nil {
180			t.Fatalf("read /proc/locks: %v", err)
181		}
182		pids := make(map[int]bool)
183		for _, line := range strings.Split(string(data), "\n") {
184			fields := strings.Fields(line)
185			// A blocked waiter looks like:
186			// "772: -> FLOCK ADVISORY WRITE 1234 103:02:2887301 0 EOF"
187			// while the holder's granted line has no "->". Locate the arrow and
188			// the FLOCK record that follows it.
189			arrow := -1
190			for i, f := range fields {
191				if f == "->" {
192					arrow = i
193					break
194				}
195			}
196			if arrow < 0 {
197				continue
198			}
199			flockIdx := -1
200			for i := arrow + 1; i < len(fields); i++ {
201				if fields[i] == "FLOCK" {
202					flockIdx = i
203					break
204				}
205			}
206			if flockIdx < 0 || flockIdx+4 >= len(fields) {
207				continue
208			}
209			// Layout after FLOCK: ADVISORY WRITE <pid> <dev>:<inode> 0 EOF
210			pidField, idField := fields[flockIdx+3], fields[flockIdx+4]
211			// Match the lock inode; the waiter PID is in any case one of our
212			// command processes, which never flock any other file.
213			if !strings.HasSuffix(idField, inodeSuffix) {
214				continue
215			}
216			if pid, err := strconv.Atoi(pidField); err == nil {
217				pids[pid] = true
218			}
219		}
220		return pids
221	}
