223	// waitUntilAllBlocked polls until every expected PID is queued waiting on the
224	// lock file. It proves both commands are simultaneously parked at the start of
225	// their serialized section before the test lets the race resolve.
226	func waitUntilAllBlocked(t *testing.T, lockPath string, want map[int]bool) {
227		t.Helper()
228		deadline := time.Now().Add(10 * time.Second)
229		for time.Now().Before(deadline) {
230			got := blockedWaiterPIDs(t, lockPath)
231			missing := false
232			for pid := range want {
233				if !got[pid] {
234					missing = true
235				}
236			}
237			if !missing {
238				return
239			}
240			time.Sleep(5 * time.Millisecond)
241		}
242		t.Fatalf("timed out waiting for commands %v to block on %q; blocked waiters: %v",
243			want, lockPath, blockedWaiterPIDs(t, lockPath))
244	}
