255	// waitCommandProcess waits for cmd to finish, failing the test if it hangs.
256	func waitCommandProcess(t *testing.T, cmd *exec.Cmd) {
257		t.Helper()
258		done := make(chan error, 1)
259		go func() { done <- cmd.Wait() }()
260		select {
261		case <-done:
262		case <-time.After(30 * time.Second):
263			_ = cmd.Process.Kill()
264			t.Fatalf("snapshot command %d did not finish after the lock was released", cmd.Process.Pid)
265		}
266	}
