268	// launchConcurrentSnapshotPair runs two independent snapshot command binaries
269	// against the same target with genuinely overlapping execution. Both are
270	// blocked together on the external gate before either can inspect the target;
271	// the gate is then released and the kernel decides the order. The returned
272	// results are bound to firstGraph / secondGraph in launch order.
273	func launchConcurrentSnapshotPair(t *testing.T, target, firstGraph, secondGraph string) (procResult, procResult) {
274		t.Helper()
275		// The barrier is proven, not guessed: both processes must be observed
276		// queued on the lock. That observation uses Linux's /proc/locks, which is
277		// absent on other unix kernels; skip there instead of timing out.
278		if _, err := os.Stat("/proc/locks"); err != nil {
279			t.Skipf("cross-process lock barrier needs Linux /proc/locks: %v", err)
280		}
281		lockPath := target + ".lock"
282		gate := holdLockGate(t, lockPath)
283	
284		var out1, err1, out2, err2 bytes.Buffer
285		cmd1 := exec.Command(snapshotCLIBin, "snapshot", firstGraph, target)
286		cmd1.Stdout, cmd1.Stderr = &out1, &err1
287		cmd2 := exec.Command(snapshotCLIBin, "snapshot", secondGraph, target)
288		cmd2.Stdout, cmd2.Stderr = &out2, &err2
289	
290		if err := cmd1.Start(); err != nil {
291			t.Fatalf("start first snapshot command: %v", err)
292		}
293		if err := cmd2.Start(); err != nil {
294			t.Fatalf("start second snapshot command: %v", err)
295		}
296		waitUntilAllBlocked(t, lockPath, map[int]bool{
297			cmd1.Process.Pid: true,
298			cmd2.Process.Pid: true,
299		})
300	
301		gate.release()
302		waitCommandProcess(t, cmd1)
303		waitCommandProcess(t, cmd2)
304	
305		return procResult{
306				label:       "first",
307				stdout:      out1.String(),
308				stderr:      err1.String(),
309				exitCode:    cmd1.ProcessState.ExitCode(),
310				sourceGraph: firstGraph,
311			}, procResult{
312				label:       "second",
313				stdout:      out2.String(),
314				stderr:      err2.String(),
315				exitCode:    cmd2.ProcessState.ExitCode(),
316				sourceGraph: secondGraph,
317			}
318	}
