655	// TestCrossProcessSnapshotPreexistingSameContentUntouched seeds the target with
656	// a valid snapshot of the same content, then submits two simultaneous saves
657	// (each reading a different equivalent encoding). Both must succeed and the
658	// existing file must remain byte-for-byte and mtime identical — no rewrite.
659	func TestCrossProcessSnapshotPreexistingSameContentUntouched(t *testing.T) {
660		want := mustSnapshotFromGraph(t, equivalentGraphForm1)
661	
662		dir := t.TempDir()
663		graph1Path, _ := writeRoundInput(t, dir, "form1.json", equivalentGraphForm1)
664		graph2Path, graph2Raw := writeRoundInput(t, dir, "form2.json", equivalentGraphForm2)
665		target := filepath.Join(dir, "snapshot.json")
666	
667		seed := saveOnce(t, graph1Path, target)
668		if seed.exitCode != 0 {
669			t.Fatalf("seed snapshot exited %d: %s", seed.exitCode, seed.stderr)
670		}
671		seedBytes, err := os.ReadFile(target)
672		if err != nil {
673			t.Fatalf("read seed snapshot: %v", err)
674		}
675		infoBefore, err := os.Stat(target)
676		if err != nil {
677			t.Fatalf("stat seed snapshot: %v", err)
678		}
679	
680		first, second := launchConcurrentSnapshotPair(t, target, graph1Path, graph2Path)
681		for _, res := range []procResult{first, second} {
682			if res.exitCode != 0 {
683				t.Errorf("%s save over identical content exited %d: %s",
684					res.label, res.exitCode, res.stderr)
685			}
686			if res.stdout != want.ContentID+"\n" {
687				t.Errorf("%s stdout = %q, want exactly %q", res.label, res.stdout, want.ContentID)
688			}
689			if res.stderr != "" {
690				t.Errorf("%s stderr = %q, want empty", res.label, res.stderr)
691			}
692		}
693	
694		gotBytes, err := os.ReadFile(target)
695		if err != nil {
696			t.Fatalf("read target after saves: %v", err)
697		}
698		if !bytes.Equal(gotBytes, seedBytes) {
699			t.Errorf("identical-content concurrent saves rewrote the target:\nbefore: %x\nafter:  %x",
700				seedBytes, gotBytes)
701		}
702		infoAfter, err := os.Stat(target)
703		if err != nil {
704			t.Fatalf("stat target after saves: %v", err)
705		}
706		if !infoAfter.ModTime().Equal(infoBefore.ModTime()) {
707			t.Errorf("identical-content concurrent saves changed mtime: %s -> %s",
708				infoBefore.ModTime(), infoAfter.ModTime())
709		}
710		// The untouched file still reads as the same valid snapshot.
711		if _, err := chainledger.ParseSnapshot(gotBytes); err != nil {
712			t.Errorf("preexisting snapshot unreadable after concurrent saves: %v", err)
713		}
714		if got, err := os.ReadFile(graph2Path); err != nil || !bytes.Equal(got, graph2Raw) {
715			t.Errorf("source graph form2 was modified")
716		}
717		assertNoLeftoverTempFiles(t, dir)
718	}
